     1	package br.com.maralta.pousada;
     2	
     3	import io.javalin.Javalin;
     4	import io.javalin.http.Context;
     5	import io.javalin.json.JavalinJackson;
     6	
     7	import java.time.LocalDate;
     8	import java.time.YearMonth;
     9	import java.time.format.DateTimeParseException;
    10	import java.util.LinkedHashMap;
    11	import java.util.List;
    12	import java.util.Map;
    13	
    14	public final class Api {
    15	    private Api() {
    16	    }
    17	
    18	    public static Javalin create(ReservationService service, Reports reports) {
    19	        Javalin app = Javalin.create(config -> config.jsonMapper(new JavalinJackson(Json.MAPPER, false)));
    20	
    21	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e));
    22	        app.exception(Exception.class, (e, ctx) -> {
    23	            e.printStackTrace();
    24	            error(ctx, new ApiException(500, "INTERNAL_ERROR", "Erro interno"));
    25	        });
    26	
    27	        app.get("/rooms", ctx -> ctx.json(Rooms.ALL.stream().map(Api::roomJson).toList()));
    28	
    29	        app.post("/reservations", ctx -> {
    30	            Reservation created = service.create(ReservationRequest.parse(ctx.body()));
    31	            ctx.status(201).json(reservationJson(created));
    32	        });
    33	        app.get("/reservations/{id}", ctx -> ctx.json(reservationJson(service.get(ctx.pathParam("id")))));
    34	        app.post("/reservations/{id}/confirmation",
    35	                ctx -> ctx.json(reservationJson(service.confirm(ctx.pathParam("id")))));
    36	        app.post("/reservations/{id}/cancellation",
    37	                ctx -> ctx.json(reservationJson(service.cancel(ctx.pathParam("id")))));
    38	        app.post("/reservations/{id}/check-in",
    39	                ctx -> ctx.json(reservationJson(service.checkIn(ctx.pathParam("id")))));
    40	        app.post("/reservations/{id}/check-out",
    41	                ctx -> ctx.json(service.checkOut(ctx.pathParam("id")).toJson()));
    42	        app.get("/reservations/{id}/document",
    43	                ctx -> ctx.json(service.secondCopy(ctx.pathParam("id")).toJson()));
    44	
    45	        app.get("/messages", ctx -> ctx.json(service.messages().stream().map(Message::toJson).toList()));
    46	
    47	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(dateParam(ctx, "date"))));
    48	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(monthParam(ctx, "month"))));
    49	        return app;
    50	    }
    51	
    52	    private static void csv(Context ctx, String body) {
    53	        ctx.contentType("text/csv; charset=utf-8").result(body);
    54	    }
    55	
    56	    private static LocalDate dateParam(Context ctx, String name) {
    57	        try {
    58	            return LocalDate.parse(required(ctx, name));
    59	        } catch (DateTimeParseException e) {
    60	            throw ApiException.invalidRequest("Data inválida em " + name + " (use 2027-07-10)");
    61	        }
    62	    }
    63	
    64	    private static YearMonth monthParam(Context ctx, String name) {
    65	        try {
    66	            return YearMonth.parse(required(ctx, name));
    67	        } catch (DateTimeParseException e) {
    68	            throw ApiException.invalidRequest("Mês inválido em " + name + " (use 2027-07)");
    69	        }
    70	    }
    71	
    72	    private static String required(Context ctx, String name) {
    73	        String value = ctx.queryParam(name);
    74	        if (value == null || value.isBlank()) {
    75	            throw ApiException.invalidRequest("Parâmetro obrigatório: " + name);
    76	        }
    77	        return value;
    78	    }
    79	
    80	    private static void error(Context ctx, ApiException e) {
    81	        ctx.status(e.httpStatus()).json(Map.of("error", e.code(), "message", e.getMessage()));
    82	    }
    83	
    84	    private static Map<String, Object> roomJson(Room room) {
    85	        Map<String, Object> json = new LinkedHashMap<>();
    86	        json.put("number", room.number());
    87	        json.put("type", room.type());
    88	        json.put("capacity", room.capacity());
    89	        json.put("nightlyRate", room.nightlyRate());
    90	        return json;
    91	    }
    92	
    93	    static Map<String, Object> reservationJson(Reservation r) {
    94	        Map<String, Object> json = new LinkedHashMap<>();
    95	        json.put("id", r.id());
    96	        json.put("roomNumber", r.roomNumber());
    97	        json.put("guestName", r.guestName());
    98	        json.put("guestEmail", r.guestEmail());
    99	        json.putAll(Identifications.allFields(r.identification()));
   100	        json.put("checkIn", r.checkIn().toString());
   101	        json.put("checkOut", r.checkOut().toString());
   102	        json.put("guests", r.guests());
   103	        json.put("ratePlan", r.ratePlan());
   104	        json.put("nights", r.nights());
   105	        json.put("subtotal", r.subtotal());
   106	        json.put("discount", r.discount());
   107	        json.put("total", r.total());
   108	        json.put("status", r.status());
   109	        json.put("amountPaid", r.amountPaid());
   110	        json.put("refund", r.refund());
   111	        return json;
   112	    }
   113	}
