=== src/main/java/br/com/maralta/pousada/ReservationService.java
     1	package br.com.maralta.pousada;
     2	
     3	import java.sql.Connection;
     4	import java.sql.SQLException;
     5	import java.util.List;
     6	import java.util.function.UnaryOperator;
     7	
     8	public class ReservationService {
     9	    private static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    10	
    11	    private final Database database;
    12	    private final ReservationRepository reservations = new ReservationRepository();
    13	    private final MessageRepository messages = new MessageRepository();
    14	
    15	    public ReservationService(Database database) {
    16	        this.database = database;
    17	    }
    18	
    19	    public Reservation create(ReservationRequest request) {
    20	        Room room = Rooms.get(request.roomNumber());
    21	        if (request.guests() > room.capacity()) {
    22	            throw ApiException.capacityExceeded(room.capacity());
    23	        }
    24	        Pricing.Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    25	        Reservation draft = new Reservation(0, room.number(), request.guestName(), request.guestEmail(),
    26	                request.identification(), request.checkIn(), request.checkOut(), request.guests(),
    27	                request.ratePlan(), quote.nights(), quote.subtotal(), quote.discount(), quote.total(),
    28	                Status.PENDING, Money.ZERO, null);
    29	        return database.inTransaction(c -> {
    30	            reservations.lockRoom(c, room.number());
    31	            if (reservations.isRoomBooked(c, room.number(), request.checkIn(), request.checkOut())) {
    32	                throw ApiException.roomUnavailable(room.number());
    33	            }
    34	            return reservations.insert(c, draft);
    35	        });
    36	    }
    37	
    38	    public Reservation get(String id) {
    39	        return database.inTransaction(c -> load(c, id, false));
    40	    }
    41	
    42	    public Reservation confirm(String id) {
    43	        return transition(id, Reservation::confirm, (c, r) -> messages.send(c, Channel.EMAIL, r.guestEmail(),
    44	                CONFIRMATION_SUBJECT, confirmationBody(r)));
    45	    }
    46	
    47	    public Reservation cancel(String id) {
    48	        return transition(id, Reservation::cancel, (c, r) -> { });
    49	    }
    50	
    51	    public Reservation checkIn(String id) {
    52	        return transition(id, Reservation::checkInGuest, (c, r) -> { });
    53	    }
    54	
    55	    public Document checkOut(String id) {
    56	        return Document.of(transition(id, Reservation::checkOutGuest, (c, r) -> { }));
    57	    }
    58	
    59	    public Document secondCopy(String id) {
    60	        Reservation reservation = get(id);
    61	        reservation.requirePaid();
    62	        return Document.of(reservation);
    63	    }
    64	
    65	    public List<Message> messages() {
    66	        return database.inTransaction(messages::findAll);
    67	    }
    68	
    69	    @FunctionalInterface
    70	    private interface AfterChange {
    71	        void run(Connection c, Reservation changed) throws SQLException;
    72	    }
    73	
    74	    /** A sequência comum das operações: trava a reserva, aplica a mudança, grava e executa o que vem depois. */
    75	    private Reservation transition(String id, UnaryOperator<Reservation> change, AfterChange after) {
    76	        return database.inTransaction(c -> {
    77	            Reservation changed = change.apply(load(c, id, true));
    78	            reservations.update(c, changed);
    79	            after.run(c, changed);
    80	            return changed;
    81	        });
    82	    }
    83	
    84	    private Reservation load(Connection c, String id, boolean forUpdate) throws SQLException {
    85	        long number;
    86	        try {
    87	            number = Long.parseLong(id);
    88	        } catch (NumberFormatException e) {
    89	            throw ApiException.reservationNotFound(id);
    90	        }
    91	        return reservations.find(c, number, forUpdate).orElseThrow(() -> ApiException.reservationNotFound(id));
    92	    }
    93	
    94	    private static String confirmationBody(Reservation reservation) {
    95	        return "Olá, " + reservation.guestName() + "!\n\n"
    96	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    97	                + Document.of(reservation).text() + "\n\n"
    98	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    99	                + "Até breve!";
   100	    }
   101	}
=== src/main/java/br/com/maralta/pousada/ReservationRepository.java
     1	package br.com.maralta.pousada;
     2	
     3	import com.fasterxml.jackson.core.type.TypeReference;
     4	
     5	import java.io.IOException;
     6	import java.sql.Connection;
     7	import java.sql.Date;
     8	import java.sql.PreparedStatement;
     9	import java.sql.ResultSet;
    10	import java.sql.SQLException;
    11	import java.sql.Statement;
    12	import java.time.LocalDate;
    13	import java.util.ArrayList;
    14	import java.util.List;
    15	import java.util.Map;
    16	import java.util.Optional;
    17	
    18	public class ReservationRepository {
    19	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, identification, check_in, "
    20	            + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    21	
    22	    /** Serializa as operações sobre um quarto até o fim da transação. */
    23	    public void lockRoom(Connection c, int roomNumber) throws SQLException {
    24	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    25	            ps.setLong(1, roomNumber);
    26	            ps.execute();
    27	        }
    28	    }
    29	
    30	    public boolean isRoomBooked(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    31	            throws SQLException {
    32	        try (PreparedStatement ps = c.prepareStatement("SELECT 1 FROM reservations WHERE room_number = ? "
    33	                + "AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?")) {
    34	            ps.setInt(1, roomNumber);
    35	            ps.setDate(2, Date.valueOf(checkOut));
    36	            ps.setDate(3, Date.valueOf(checkIn));
    37	            try (ResultSet rs = ps.executeQuery()) {
    38	                return rs.next();
    39	            }
    40	        }
    41	    }
    42	
    43	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    44	        try (PreparedStatement ps = c.prepareStatement("INSERT INTO reservations (room_number, guest_name, "
    45	                + "guest_email, identification, check_in, check_out, guests, rate_plan, nights, subtotal, discount, "
    46	                + "total, status, amount_paid, refund) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
    47	                Statement.RETURN_GENERATED_KEYS)) {
    48	            bind(ps, r, 1);
    49	            ps.executeUpdate();
    50	            try (ResultSet keys = ps.getGeneratedKeys()) {
    51	                keys.next();
    52	                return withId(r, keys.getLong("id"));
    53	            }
    54	        }
    55	    }
    56	
    57	    public void update(Connection c, Reservation r) throws SQLException {
    58	        try (PreparedStatement ps = c.prepareStatement("UPDATE reservations SET status = ?, amount_paid = ?, "
    59	                + "refund = ? WHERE id = ?")) {
    60	            ps.setString(1, r.status().name());
    61	            ps.setBigDecimal(2, r.amountPaid());
    62	            ps.setBigDecimal(3, r.refund());
    63	            ps.setLong(4, r.id());
    64	            ps.executeUpdate();
    65	        }
    66	    }
    67	
    68	    public Optional<Reservation> find(Connection c, long id, boolean forUpdate) throws SQLException {
    69	        String sql = "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : "");
    70	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    71	            ps.setLong(1, id);
    72	            try (ResultSet rs = ps.executeQuery()) {
    73	                return rs.next() ? Optional.of(map(rs)) : Optional.empty();
    74	            }
    75	        }
    76	    }
    77	
    78	    /** Reservas pagas que ocupam um quarto na noite, por número de quarto. */
    79	    public List<Reservation> findPaidOccupying(Connection c, LocalDate night) throws SQLException {
    80	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE status IN ('CONFIRMED','CHECKED_IN',"
    81	                + "'CHECKED_OUT') AND check_in <= ? AND check_out > ? ORDER BY room_number, id",
    82	                night, night);
    83	    }
    84	
    85	    /** Reservas com entrada no intervalo [from, to), em ordem de entrada e número. */
    86	    public List<Reservation> findStartingBetween(Connection c, LocalDate from, LocalDate to) throws SQLException {
    87	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
    88	                + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id", from, to);
    89	    }
    90	
    91	    private List<Reservation> query(Connection c, String sql, LocalDate a, LocalDate b) throws SQLException {
    92	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    93	            ps.setDate(1, Date.valueOf(a));
    94	            ps.setDate(2, Date.valueOf(b));
    95	            try (ResultSet rs = ps.executeQuery()) {
    96	                List<Reservation> result = new ArrayList<>();
    97	                while (rs.next()) {
    98	                    result.add(map(rs));
    99	                }
   100	                return result;
   101	            }
   102	        }
   103	    }
   104	
   105	    private void bind(PreparedStatement ps, Reservation r, int i) throws SQLException {
   106	        try {
   107	            ps.setInt(i++, r.roomNumber());
   108	            ps.setString(i++, r.guestName());
   109	            ps.setString(i++, r.guestEmail());
   110	            ps.setString(i++, Json.MAPPER.writeValueAsString(r.identification().fields()));
   111	        } catch (IOException e) {
   112	            throw new IllegalStateException(e);
   113	        }
   114	        ps.setDate(i++, Date.valueOf(r.checkIn()));
   115	        ps.setDate(i++, Date.valueOf(r.checkOut()));
   116	        ps.setInt(i++, r.guests());
   117	        ps.setString(i++, r.ratePlan().name());
   118	        ps.setInt(i++, r.nights());
   119	        ps.setBigDecimal(i++, r.subtotal());
   120	        ps.setBigDecimal(i++, r.discount());
   121	        ps.setBigDecimal(i++, r.total());
   122	        ps.setString(i++, r.status().name());
   123	        ps.setBigDecimal(i++, r.amountPaid());
   124	        ps.setBigDecimal(i, r.refund());
   125	    }
   126	
   127	    private Reservation map(ResultSet rs) throws SQLException {
   128	        try {
   129	            Map<String, String> fields = Json.MAPPER.readValue(rs.getString("identification"),
   130	                    new TypeReference<Map<String, String>>() { });
   131	            return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
   132	                    rs.getString("guest_email"), Identifications.from(fields),
   133	                    rs.getDate("check_in").toLocalDate(), rs.getDate("check_out").toLocalDate(),
   134	                    rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), rs.getInt("nights"),
   135	                    rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
   136	                    Status.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"),
   137	                    rs.getBigDecimal("refund"));
   138	        } catch (IOException e) {
   139	            throw new IllegalStateException(e);
   140	        }
   141	    }
   142	
