    30	        inTransaction(c -> {
    31	            try (Statement st = c.createStatement()) {
    32	                st.execute("SELECT pg_advisory_xact_lock(7070)");
    33	                st.execute("""
    34	                        CREATE TABLE IF NOT EXISTS reservations (
