     8	
     9	/** Registro das formas de identificação aceitas. */
    10	public final class Identifications {
    11	    /** Uma forma de identificação: seus campos (todos obrigatórios) e como montá-la. */
    12	    public record Kind(String name, List<String> fieldNames, Function<Map<String, String>, Identification> factory) {
    13	    }
    14	
    15	    public static final List<Kind> KINDS = List.of(CpfIdentification.KIND, CnpjIdentification.KIND,
    16	            PassportIdentification.KIND);
    17	
    18	    private Identifications() {
    19	    }
    20	
    21	    /** Nomes de todos os campos de identificação que a API expõe. */
    22	    public static List<String> allFieldNames() {
    23	        return KINDS.stream().flatMap(k -> k.fieldNames().stream()).toList();
    24	    }
    25	
    26	    /** Todos os campos, com null nos que não se aplicam. */
    27	    public static Map<String, String> allFields(Identification identification) {
    28	        Map<String, String> result = new LinkedHashMap<>();
    29	        for (String name : allFieldNames()) {
    30	            result.put(name, identification.fields().get(name));
    31	        }
    32	        return result;
    33	    }
    34	
    35	    /** Monta a identificação a partir dos campos informados; exige exatamente uma forma, completa. */
    36	    public static Identification from(Map<String, String> given) {
    37	        List<Kind> used = new ArrayList<>();
    38	        for (Kind kind : KINDS) {
    39	            if (kind.fieldNames().stream().anyMatch(given::containsKey)) {
    40	                used.add(kind);
    41	            }
    42	        }
    43	        if (used.size() != 1) {
    44	            throw ApiException.invalidRequest("Informe a identificação de um só jeito: "
    45	                    + KINDS.stream().map(k -> String.join(" + ", k.fieldNames())).toList());
    46	        }
    47	        Kind kind = used.get(0);
    48	        for (String name : kind.fieldNames()) {
    49	            String value = given.get(name);
    50	            if (value == null || value.isBlank()) {
    51	                throw ApiException.invalidRequest("Campo obrigatório: " + name);
    52	            }
    53	        }
    54	        return kind.factory().apply(given);
    55	    }
    56	}
