    22	    public static ReservationRequest parse(String body) {
    23	        JsonNode json;
    24	        try {
    25	            json = Json.MAPPER.readTree(body);
    26	        } catch (JsonProcessingException e) {
    27	            throw ApiException.invalidRequest("O corpo não é um JSON válido");
    28	        }
    29	        if (json == null || !json.isObject()) {
    30	            throw ApiException.invalidRequest("O corpo deve ser um objeto JSON");
    31	        }
    32	        LocalDate checkIn = date(json, "checkIn");
    33	        LocalDate checkOut = date(json, "checkOut");
    34	        if (!checkOut.isAfter(checkIn)) {
    35	            throw ApiException.invalidRequest("A saída deve ser depois da entrada");
    36	        }
    37	        int guests = integer(json, "guests");
    38	        if (guests < 1) {
    39	            throw ApiException.invalidRequest("É preciso pelo menos um hóspede");
    40	        }
    41	        return new ReservationRequest(integer(json, "roomNumber"), text(json, "guestName"),
    42	                text(json, "guestEmail"), identification(json), checkIn, checkOut, guests, ratePlan(json));
    43	    }
