    52	            if (!value.isTextual()) {
    53	                throw ApiException.invalidRequest("Campo " + name + " deve ser um texto");
    54	            }
    55	            given.put(name, value.asText());
    56	        }
    57	        return Identifications.from(given);
    58	    }
