 21	/** Teste ponta a ponta; usa um schema descartável no banco de DB_URL (ignorado se o banco não existir). */
 22	class ApiTest {
 23	    static String schema = "teste_" + UUID.randomUUID().toString().replace("-", "");
 24	    static Database database;
 25	    static Javalin app;
 26	    static HttpClient http = HttpClient.newHttpClient();
 27	    static String base;
 28	
 29	    @BeforeAll
 30	    static void start() throws Exception {
 31	        String url = System.getenv("DB_URL");
 32	        Assumptions.assumeTrue(url != null, "DB_URL ausente");
 33	        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 34	             Statement st = c.createStatement()) {
 35	            st.execute("CREATE SCHEMA " + schema);
 36	        } catch (Exception e) {
 37	            Assumptions.abort("Banco indisponível: " + e.getMessage());
 38	        }
 39	        database = new Database(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema,
 40	                System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 41	        app = Api.create(new ReservationService(database), new Reports(database)).start(0);
 42	        base = "http://localhost:" + app.port();
 43	    }
 44	
 45	    @AfterAll
 46	    static void stop() throws Exception {
 47	        if (app != null) {
 48	            app.stop();
 49	            database.close();
 50	            try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
 51	                    System.getenv("DB_PASSWORD")); Statement st = c.createStatement()) {
 52	                st.execute("DROP SCHEMA " + schema + " CASCADE");
 53	            }
 54	        }
 55	    }
