 63	    static Res call(String method, String path, String body) throws Exception {
 64	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 65	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 66	        HttpResponse<String> r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 67	        return new Res(r.statusCode(), r.body(), r.headers().firstValue("content-type").orElse(""));
